#!/usr/bin/env node
/* Tests the slack-api skill client (scripts/slack_api.cjs) against a local mock Slack API. */

const http = require('node:http');
const path = require('node:path');
const { main } = require(path.join(__dirname, 'slack-api', 'scripts', 'slack_api.cjs'));

let passed = 0;
let failed = 0;

function report(name, ok, extra) {
  if (ok) {
    passed += 1;
    console.log(`PASS ${name}`);
  } else {
    failed += 1;
    console.log(`FAIL ${name}${extra ? ` - ${extra}` : ''}`);
  }
}

function sendJson(res, obj, status = 200) {
  const raw = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(raw),
  });
  res.end(raw);
}

function capture(fn) {
  const origOut = process.stdout.write;
  const origErr = process.stderr.write;
  let out = '';
  let err = '';
  process.stdout.write = (chunk) => {
    out += String(chunk);
    return true;
  };
  process.stderr.write = (chunk) => {
    err += String(chunk);
    return true;
  };
  return Promise.resolve()
    .then(fn)
    .finally(() => {
      process.stdout.write = origOut;
      process.stderr.write = origErr;
    })
    .then(() => ({ out, err }));
}

function createHandler() {
  return (req, res) => {
    const url = new URL(req.url, 'http://127.0.0.1');
    let raw = '';
    req.on('data', (c) => {
      raw += c;
    });
    req.on('end', () => {
      let body = {};
      try {
        body = JSON.parse(raw || '{}');
      } catch (e) {
        body = {};
      }
      const auth = req.headers.authorization || '';

      if (url.pathname === '/api/chat.postMessage') {
        if (auth !== 'Bearer xoxb-test') {
          return sendJson(res, { ok: false, error: 'invalid_auth' });
        }
        return sendJson(res, {
          ok: true,
          channel: body.channel,
          ts: '1712345678.000000',
          message: { text: body.text },
        });
      }

      if (url.pathname === '/api/conversations.list') {
        if (auth !== 'Bearer xoxb-test') {
          return sendJson(res, { ok: false, error: 'invalid_auth' });
        }
        if (body.cursor === 'abc') {
          return sendJson(res, {
            ok: true,
            channels: [{ id: 'C2', name: 'random' }],
            response_metadata: { next_cursor: '' },
          });
        }
        return sendJson(res, {
          ok: true,
          channels: [{ id: 'C1', name: 'general' }],
          response_metadata: { next_cursor: 'abc' },
        });
      }

      if (url.pathname === '/api/rate.limited') {
        res.writeHead(429, { 'Retry-After': '7' });
        return res.end('{"ok":false,"error":"rate_limited"}');
      }

      if (url.pathname === '/api/notjson') {
        res.writeHead(200, { 'Content-Type': 'text/plain' });
        return res.end('this is not JSON');
      }

      if (url.pathname === '/api/large.payload') {
        return sendJson(res, { ok: true, data: 'x'.repeat(50000) });
      }

      if (url.pathname === '/api/empty.list') {
        return sendJson(res, { ok: true, items: [], response_metadata: { next_cursor: '' } });
      }

      res.writeHead(404);
      res.end('not found');
    });
  };
}

async function runTests() {
  const savedToken = process.env.SLACK_TOKEN;
  delete process.env.SLACK_TOKEN;

  process.exitCode = 0;
  let r = await capture(() => main([]));
  report('usage on no args', r.err.includes('Usage:') && process.exitCode === 2, `exit=${process.exitCode}`);

  process.exitCode = 0;
  r = await capture(() => main(['--bogus']));
  report('unknown option rejected', r.err.includes('Unknown option') && process.exitCode === 1, `exit=${process.exitCode}`);

  process.exitCode = 0;
  r = await capture(() => main(['chat.postMessage', '{"channel":"#general","text":"hi"}']));
  report('missing token fails cleanly', r.err.includes('No token') && process.exitCode === 1, `exit=${process.exitCode} err=${r.err.trim()}`);

  process.exitCode = 0;
  r = await capture(() => main(['chat.postMessage', '{oops']));
  report('invalid JSON body fails cleanly', r.err.includes('Invalid JSON body') && process.exitCode === 1, `exit=${process.exitCode} err=${r.err.trim()}`);

  process.exitCode = 0;
  r = await capture(() => main(['../../etc/passwd', '{}', '--token', 'xoxb-test']));
  report('invalid method name rejected', r.err.includes('Invalid method name') && process.exitCode === 1, `exit=${process.exitCode} err=${r.err.trim()}`);

  const server = http.createServer(createHandler());
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const baseUrl = `http://127.0.0.1:${server.address().port}`;
  process.env.SLACK_API_BASE_URL = baseUrl;

  try {
    process.env.SLACK_TOKEN = 'xoxb-test';

    process.exitCode = 0;
    r = await capture(() => main(['chat.postMessage', '{"channel":"#general","text":"hello"}']));
    let posted = null;
    try {
      posted = JSON.parse(r.out);
    } catch (e) {
      posted = null;
    }
    report(
      'post message ok (token via env)',
      process.exitCode === 0 && posted && posted.ok === true && posted.channel === '#general' && posted.message.text === 'hello',
      `exit=${process.exitCode} out=${r.out.slice(0, 200)}`,
    );

    process.exitCode = 0;
    r = await capture(() => main(['chat.postMessage', '{"channel":"#general","text":"hi"}', '--token', 'xoxb-bad']));
    report('invalid auth reported', r.err.includes('Slack API error: invalid_auth') && process.exitCode === 1, `exit=${process.exitCode} err=${r.err.trim()}`);

    process.exitCode = 0;
    r = await capture(() => main(['conversations.list', '{"limit":1}', '--token', 'xoxb-test', '--paginate']));
    let listed = null;
    try {
      listed = JSON.parse(r.out);
    } catch (e) {
      listed = null;
    }
    report(
      'paginate merges all pages',
      process.exitCode === 0 && listed && Array.isArray(listed.channels) && listed.channels.length === 2 && listed.channels.some((c) => c.id === 'C1') && listed.channels.some((c) => c.id === 'C2'),
      `exit=${process.exitCode} out=${r.out.slice(0, 300)}`,
    );

    process.exitCode = 0;
    r = await capture(() => main(['conversations.list', '{"limit":1}', '--token', 'xoxb-test']));
    let single = null;
    try {
      single = JSON.parse(r.out);
    } catch (e) {
      single = null;
    }
    report('single page without --paginate', process.exitCode === 0 && single && single.channels.length === 1 && single.channels[0].id === 'C1', `exit=${process.exitCode} out=${r.out.slice(0, 200)}`);

    process.exitCode = 0;
    r = await capture(() => main(['rate.limited', '{}', '--token', 'xoxb-test']));
    report('rate limit reported with retry-after', r.err.includes('Rate limited') && r.err.includes('7') && process.exitCode === 1, `exit=${process.exitCode} err=${r.err.trim()}`);

    process.exitCode = 0;
    r = await capture(() => main(['notjson', '{}', '--token', 'xoxb-test']));
    report('non-JSON response reported', r.err.includes('Invalid JSON response') && process.exitCode === 1, `exit=${process.exitCode} err=${r.err.trim()}`);

    process.exitCode = 0;
    r = await capture(() => main(['large.payload', '{}', '--token', 'xoxb-test']));
    report('large output truncated by default', process.exitCode === 0 && r.out.includes('truncated') && r.out.length < 25000, `outLen=${r.out.length}`);

    process.exitCode = 0;
    r = await capture(() => main(['large.payload', '{}', '--token', 'xoxb-test', '--no-truncate']));
    report('--no-truncate keeps full output', process.exitCode === 0 && r.out.length > 49000, `outLen=${r.out.length}`);

    process.exitCode = 0;
    r = await capture(() => main(['empty.list', '{}', '--token', 'xoxb-test', '--paginate']));
    report('paginate handles non-array response', process.exitCode === 0 && r.out.includes('"ok": true'), `exit=${process.exitCode} out=${r.out.slice(0, 120)}`);
  } finally {
    delete process.env.SLACK_API_BASE_URL;
    if (savedToken === undefined) {
      delete process.env.SLACK_TOKEN;
    } else {
      process.env.SLACK_TOKEN = savedToken;
    }
    server.close();
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

runTests().catch((err) => {
  console.error(`Test harness error: ${err.message}`);
  process.exit(1);
});

#!/usr/bin/env node
/* Validates and packages the slack-api skill into a distributable .skill (ZIP) file.
 * Mirrors skill-creator's package_skill.cjs + validate_skill.cjs with a pure-Node ZIP writer.
 */

const fs = require('node:fs');
const path = require('node:path');

const SKILL_DIR = path.join(__dirname, 'slack-api');
const OUT_FILE = path.join(__dirname, 'slack-api.skill');

/* ---------- 1. Cleanup scaffolding (example files, empty assets dir) ---------- */

function removeIfExists(file) {
  if (fs.existsSync(file)) {
    fs.rmSync(file);
    console.log(`Removed scaffolding file: ${path.relative(SKILL_DIR, file)}`);
  }
}

removeIfExists(path.join(SKILL_DIR, 'scripts', 'example_script.cjs'));
removeIfExists(path.join(SKILL_DIR, 'references', 'example_reference.md'));
removeIfExists(path.join(SKILL_DIR, 'assets', 'example_asset.txt'));
const assetsDir = path.join(SKILL_DIR, 'assets');
if (fs.existsSync(assetsDir) && fs.readdirSync(assetsDir).length === 0) {
  fs.rmdirSync(assetsDir);
  console.log('Removed empty assets/ directory.');
}

/* ---------- 2. Validation (mirrors validate_skill.cjs) ---------- */

function getAllFiles(dir, fileList = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      getAllFiles(full, fileList);
    } else {
      fileList.push(full);
    }
  }
  return fileList;
}

function validateSkill(skillPath) {
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    return { valid: false, message: 'SKILL.md not found' };
  }
  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) {
    return { valid: false, message: 'No YAML frontmatter found' };
  }
  const parts = content.split('---');
  if (parts.length < 3) {
    return { valid: false, message: 'Invalid frontmatter format' };
  }
  const frontmatter = parts[1];
  const nameMatch = frontmatter.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatter.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
  if (!nameMatch) {
    return { valid: false, message: 'Missing "name" in frontmatter' };
  }
  if (!descMatch) {
    return { valid: false, message: 'Description must be a single-line string: description: ...' };
  }
  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || ''
  ).trim();
  if (description.includes('\n')) {
    return { valid: false, message: 'Description must be a single line (no newlines)' };
  }
  if (!/^[a-z0-9-]+$/.test(name)) {
    return { valid: false, message: `Name "${name}" should be hyphen-case` };
  }
  if (description.length > 1024) {
    return { valid: false, message: 'Description is too long (max 1024)' };
  }
  for (const file of getAllFiles(skillPath)) {
    if (fs.readFileSync(file, 'utf8').includes('TODO:')) {
      return { valid: false, message: `Unresolved TODO in ${path.relative(skillPath, file)}` };
    }
  }
  return { valid: true, message: 'Skill is valid!' };
}

console.log('Validating skill...');
const result = validateSkill(SKILL_DIR);
if (!result.valid) {
  console.error(`Validation failed: ${result.message}`);
  process.exit(1);
}
console.log(`Skill is valid! (${result.message})`);

/* ---------- 3. ZIP writer (stored method, no external dependencies) ---------- */

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  }
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(d) {
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >>> 1);
  const date = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time: time & 0xffff, date: date & 0xffff };
}

function makeZip(entries) {
  const chunks = [];
  const central = [];
  let offset = 0;
  const now = new Date();
  const { time, date } = dosDateTime(now);

  for (const entry of entries) {
    const nameBuf = Buffer.from(entry.name, 'utf8');
    const crc = crc32(entry.data);

    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); // local file header signature
    lh.writeUInt16LE(20, 4); // version needed
    lh.writeUInt16LE(0, 6); // flags
    lh.writeUInt16LE(0, 8); // method: stored
    lh.writeUInt16LE(time, 10);
    lh.writeUInt16LE(date, 12);
    lh.writeUInt32LE(crc, 14);
    lh.writeUInt32LE(entry.data.length, 18); // compressed size
    lh.writeUInt32LE(entry.data.length, 22); // uncompressed size
    lh.writeUInt16LE(nameBuf.length, 26);
    lh.writeUInt16LE(0, 28); // extra length
    chunks.push(lh, nameBuf, entry.data);

    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); // central directory signature
    ch.writeUInt16LE(20, 4); // version made by
    ch.writeUInt16LE(20, 6); // version needed
    ch.writeUInt16LE(0, 8); // flags
    ch.writeUInt16LE(0, 10); // method: stored
    ch.writeUInt16LE(time, 12);
    ch.writeUInt16LE(date, 14);
    ch.writeUInt32LE(crc, 16);
    ch.writeUInt32LE(entry.data.length, 20); // compressed size
    ch.writeUInt32LE(entry.data.length, 24); // uncompressed size
    ch.writeUInt16LE(nameBuf.length, 28);
    ch.writeUInt16LE(0, 30); // extra length
    ch.writeUInt16LE(0, 32); // comment length
    ch.writeUInt16LE(0, 34); // disk number
    ch.writeUInt16LE(0, 36); // internal attributes
    ch.writeUInt32LE(0, 38); // external attributes
    ch.writeUInt32LE(offset, 42); // local header offset
    central.push(ch, nameBuf);

    offset += 30 + nameBuf.length + entry.data.length;
  }

  const centralStart = offset;
  const centralBuf = Buffer.concat(central);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  eocd.writeUInt16LE(0, 4); // disk number
  eocd.writeUInt16LE(0, 6); // central directory disk
  eocd.writeUInt16LE(entries.length, 8); // entries on this disk
  eocd.writeUInt16LE(entries.length, 10); // total entries
  eocd.writeUInt32LE(centralBuf.length, 12);
  eocd.writeUInt32LE(centralStart, 16);
  eocd.writeUInt16LE(0, 20); // comment length
  return Buffer.concat([...chunks, centralBuf, eocd]);
}

/* ---------- 4. Package and verify ---------- */

const fileList = getAllFiles(SKILL_DIR);
const entries = fileList.map((file) => ({
  name: path.relative(SKILL_DIR, file).split(path.sep).join('/'),
  data: fs.readFileSync(file),
}));

const zipBuf = makeZip(entries);
fs.writeFileSync(OUT_FILE, zipBuf);
console.log(`Packaged ${entries.length} file(s) into ${path.basename(OUT_FILE)}`);

/* Self-check: re-read the zip and verify structure and CRCs. */
function verifyZip(buf, expectedFiles) {
  if (buf.readUInt32LE(buf.length - 22) !== 0x06054b50) {
    throw new Error('End-of-central-directory signature missing');
  }
  const count = buf.readUInt16LE(buf.length - 14);
  const cdSize = buf.readUInt32LE(buf.length - 10);
  const cdOffset = buf.readUInt32LE(buf.length - 6);
  if (cdOffset + cdSize !== buf.length - 22) {
    throw new Error('Central directory bounds mismatch');
  }
  let off = cdOffset;
  const names = [];
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(off) !== 0x02014b50) {
      throw new Error(`Central directory entry ${i} signature missing`);
    }
    const method = buf.readUInt16LE(off + 10);
    const crc = buf.readUInt32LE(off + 16);
    const compSize = buf.readUInt32LE(off + 20);
    const uncompSize = buf.readUInt32LE(off + 24);
    const nameLen = buf.readUInt16LE(off + 28);
    const extraLen = buf.readUInt16LE(off + 30);
    const commentLen = buf.readUInt16LE(off + 32);
    const localOffset = buf.readUInt32LE(off + 42);
    const name = buf.toString('utf8', off + 46, off + 46 + nameLen);
    names.push(name);

    if (buf.readUInt32LE(localOffset) !== 0x04034b50) {
      throw new Error(`Local file header missing for ${name}`);
    }
    if (method !== 0) {
      throw new Error(`Expected stored (0) compression for ${name}, got ${method}`);
    }
    if (compSize !== uncompSize) {
      throw new Error(`Size mismatch for ${name}`);
    }
    const lNameLen = buf.readUInt16LE(localOffset + 26);
    const lExtraLen = buf.readUInt16LE(localOffset + 28);
    const dataStart = localOffset + 30 + lNameLen + lExtraLen;
    const data = buf.subarray(dataStart, dataStart + uncompSize);
    if (crc32(data) !== crc) {
      throw new Error(`CRC mismatch for ${name}`);
    }
    off += 46 + nameLen + extraLen + commentLen;
  }
  for (const expected of expectedFiles) {
    if (!names.includes(expected)) {
      throw new Error(`Missing expected entry: ${expected}`);
    }
  }
  return names;
}

const expectedFiles = ['SKILL.md', 'scripts/slack_api.cjs', 'references/api.md'];
const verified = verifyZip(fs.readFileSync(OUT_FILE), expectedFiles);
console.log(`Verified zip: ${verified.join(', ')}`);
console.log(`Successfully packaged skill to: ${OUT_FILE}`);

#!/usr/bin/env node
/**
 * Generic Slack Web API client for the slack-api skill.
 *
 * Usage:
 *   node scripts/slack_api.cjs <method> [jsonBody] [--token TOKEN] [--paginate] [--no-truncate]
 *
 * Environment:
 *   SLACK_TOKEN        Bot token (xoxb-...). Used unless --token is passed.
 *   SLACK_API_BASE_URL Override for the API base URL (default https://slack.com/api).
 *                      Intended for tests and proxies.
 *
 * Output conventions (agent-friendly):
 *   - Success: JSON response on stdout, exit code 0.
 *   - Failure: a single `Failure: <message>` line on stderr, exit code 1.
 *   - Responses over 20000 characters are truncated unless --no-truncate is passed.
 */

const https = require('node:https');
const http = require('node:http');

const MAX_OUTPUT_CHARS = 20000;
const MAX_PAGES = 200;
const METHOD_RE = /^[a-zA-Z0-9_.]+$/;

function usage() {
  return [
    'Usage: node scripts/slack_api.cjs <method> [jsonBody] [--token TOKEN] [--paginate] [--no-truncate]',
    '',
    '  <method>      Slack Web API method, e.g. chat.postMessage',
    '  [jsonBody]    JSON object as a string, e.g. \'{"channel":"#general","text":"hi"}\'',
    '  --token       Bot token (xoxb-...). Falls back to $SLACK_TOKEN.',
    '  --paginate    Follow response_metadata.next_cursor and merge all pages.',
    '  --no-truncate Do not truncate large responses.',
  ].join('\n');
}

function parseArgs(argv) {
  const opts = { method: null, body: {}, token: null, paginate: false, truncate: true };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--token') {
      opts.token = argv[++i];
    } else if (arg.startsWith('--token=')) {
      opts.token = arg.slice('--token='.length);
    } else if (arg === '--paginate') {
      opts.paginate = true;
    } else if (arg === '--no-truncate') {
      opts.truncate = false;
    } else if (arg.startsWith('--')) {
      throw new Error(`Unknown option: ${arg}`);
    } else {
      positional.push(arg);
    }
  }
  if (positional.length > 0) {
    opts.method = positional[0];
  }
  if (positional.length > 1) {
    let parsed;
    try {
      parsed = JSON.parse(positional[1]);
    } catch (err) {
      throw new Error(`Invalid JSON body: ${err.message}`);
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('Invalid JSON body: expected a JSON object');
    }
    opts.body = parsed;
  }
  return opts;
}

function truncateText(text, max) {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}...[truncated]`;
}

function post(baseUrl, method, token, body) {
  const url = new URL(`/api/${method}`, baseUrl);
  const payload = JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const mod = url.protocol === 'https:' ? https : http;
    const req = mod.request(
      url,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          Authorization: `Bearer ${token}`,
          'User-Agent': 'slack-api-skill/1.0',
          'Content-Length': Buffer.byteLength(payload),
        },
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const raw = Buffer.concat(chunks).toString('utf8');
          let json = null;
          try {
            json = JSON.parse(raw);
          } catch (err) {
            json = null;
          }
          resolve({ status: res.statusCode, headers: res.headers, body: raw, json });
        });
      },
    );
    req.on('error', (err) => reject(new Error(`Request failed: ${err.message}`)));
    req.setTimeout(30000, () => req.destroy(new Error('Request timed out after 30s')));
    req.end(payload);
  });
}

function findArrayKey(obj) {
  if (!obj || typeof obj !== 'object') return null;
  for (const key of Object.keys(obj)) {
    if (
      Array.isArray(obj[key]) &&
      obj[key].length > 0 &&
      obj[key].every((item) => item && typeof item === 'object')
    ) {
      return key;
    }
  }
  return null;
}

function output(obj, opts) {
  let text = JSON.stringify(obj, null, 2);
  if (opts.truncate && text.length > MAX_OUTPUT_CHARS) {
    text = `${text.slice(0, MAX_OUTPUT_CHARS)}\n...[truncated; rerun with --no-truncate for the full response]`;
  }
  process.stdout.write(`${text}\n`);
}

async function run(opts) {
  const token = opts.token || process.env.SLACK_TOKEN;
  if (!token) {
    throw new Error('No token: pass --token TOKEN or set SLACK_TOKEN');
  }
  if (!METHOD_RE.test(opts.method)) {
    throw new Error(`Invalid method name: ${opts.method}`);
  }
  const baseUrl = process.env.SLACK_API_BASE_URL || 'https://slack.com/api';

  let body = opts.body;
  let merged = null;
  let pages = 0;

  while (true) {
    pages += 1;
    if (pages > MAX_PAGES) {
      throw new Error(`Stopped after ${MAX_PAGES} pages (possible pagination loop)`);
    }
    const res = await post(baseUrl, opts.method, token, body);

    if (res.status === 429) {
      const retryAfter = res.headers['retry-after'] || 'unknown';
      throw new Error(`Rate limited (HTTP 429). Retry after ${retryAfter} second(s).`);
    }
    if (res.status < 200 || res.status >= 300) {
      throw new Error(`HTTP ${res.status}: ${truncateText(res.body, 500)}`);
    }
    if (!res.json) {
      throw new Error(`Invalid JSON response: ${truncateText(res.body, 500)}`);
    }
    if (res.json.ok === false) {
      const detail = res.json.error || 'unknown error';
      const needed = res.json.needed ? ` (add scope: ${res.json.needed})` : '';
      throw new Error(`Slack API error: ${detail}${needed}`);
    }

    if (!opts.paginate) {
      output(res.json, opts);
      return;
    }

    const key = findArrayKey(res.json);
    if (!key) {
      output(res.json, opts);
      return;
    }
    if (!merged) {
      merged = { ...res.json };
      merged[key] = [...res.json[key]];
    } else {
      merged[key] = (merged[key] || []).concat(res.json[key] || []);
    }

    const cursor = res.json.response_metadata && res.json.response_metadata.next_cursor;
    if (!cursor) {
      output(merged, opts);
      return;
    }
    body = { ...body, cursor };
  }
}

async function main(argv) {
  const args = argv || process.argv.slice(2);
  try {
    const opts = parseArgs(args);
    if (!opts.method) {
      process.stderr.write(`${usage()}\n`);
      process.exitCode = 2;
      return;
    }
    await run(opts);
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exitCode = 1;
  }
}

if (require.main === module) {
  main();
}

module.exports = { main };
